,"existing_name":"Ethan Tan Jing Zhou","match_method":"name_or_alias","handle":"ethan-tan-jing-zhou"}]$data$::jsonb;
BEGIN
 SELECT id INTO STRICT event_uuid FROM public.regatta_events WHERE slug='raffles-marina-optimist-regatta-2024';
 INSERT INTO public.sailors(name,handle,sail_number,club,gender) VALUES('Leyla Sherif Ahmed Khalil','leyla-sherif-ahmed-khalil','177','N/A','F') ON CONFLICT(handle) DO NOTHING;
 UPDATE public.sailor_aliases SET sailor_id=(SELECT id FROM public.sailors WHERE handle='leyla-sherif-ahmed-khalil') WHERE lower(alias_name)='leyla sherif ahmed khalil' AND sailor_id=(SELECT id FROM public.sailors WHERE handle='dani-sherif-ahmed-khalil-opwouuw');
 PERFORM pg_advisory_xact_lock(hashtext('rmor-2024-final-results'));
 IF jsonb_array_length(payload) <> 174 THEN RAISE EXCEPTION 'Expected 174 source entries'; END IF;
 FOR fleet IN SELECT unnest(ARRAY['gold','silver']) LOOP
  expected := CASE WHEN fleet='gold' THEN 86 ELSE 88 END;
  doc := CASE WHEN fleet='gold' THEN 'https://www.racingrulesofsailing.org/documents/102965' ELSE 'https://www.racingrulesofsailing.org/documents/102962' END;
  IF fleet='gold' THEN
   SELECT id INTO STRICT sheet_uuid FROM public.regattas WHERE slug='raffles-marina-optimist-gold-import-may-24-2024-05-25' FOR UPDATE;
   IF (SELECT count(*) FROM public.regatta_results WHERE regatta_id=sheet_uuid) <> 86 THEN RAISE EXCEPTION 'Gold roster changed; review before replacing'; END IF;
  ELSE
   INSERT INTO public.regattas(name,slug,date,end_date,total_fleet_size,division,race_count,geography,boat_class,counts_for_ranking,status,event_id,venue,nor_url)
   VALUES ('Raffles Marina Optimist Regatta 2024 (Silver)','raffles-marina-optimist-2024-silver','2024-05-25','2024-05-26',88,'Silver',5,'SGP','Optimist',true,'published',event_uuid,'Raffles Marina, Singapore','https://www.racingrulesofsailing.org/documents/8341/event')
   ON CONFLICT (slug) DO UPDATE SET updated_at=now() RETURNING id INTO sheet_uuid;
  END IF;
  UPDATE public.regattas SET name='Raffles Marina Optimist Regatta 2024 (' || initcap(fleet) || ')',date='2024-05-25',end_date='2024-05-26',total_fleet_size=expected,race_count=CASE WHEN fleet='gold' THEN 6 ELSE 5 END,event_id=event_uuid,venue='Raffles Marina, Singapore',nor_url='https://www.racingrulesofsailing.org/documents/8341/event',status='published',reviewed_at=now(),updated_at=now() WHERE id=sheet_uuid;
  FOR item IN SELECT value FROM jsonb_array_elements(payload) WHERE value->>'fleet'=fleet LOOP
   SELECT id INTO STRICT sailor_uuid FROM public.sailors WHERE handle=item->>'handle';
   IF item->>'sailor_id' IS NOT NULL AND sailor_uuid <> (item->>'sailor_id')::uuid THEN RAISE EXCEPTION 'Sailor identity changed: %',item->>'handle'; END IF;
   IF fleet='gold' AND NOT EXISTS (SELECT 1 FROM public.regatta_results WHERE regatta_id=sheet_uuid AND sailor_id=sailor_uuid) THEN RAISE EXCEPTION 'Gold sailor missing: %',item->>'handle'; END IF;
   INSERT INTO public.regatta_results(sailor_id,regatta_id,rank,nett_score,total_score,gender,evidence_url,evidence_name,evidence_type,official_url,evidence_notes,verification_status,verified_at)
   VALUES(sailor_uuid,sheet_uuid,(item->>'rank')::integer,(item->>'nett')::real,(item->>'total')::real,item->>'gender',doc,initcap(fleet)||' Fleet Day 2 Version 2 final results','link',doc,'Official source name: '||(item->>'name')||'; historical sail number: '||(item->>'sail')||'; source age division: '||coalesce(item->>'age_division','not listed')||'; final results 26 May 2024; one discard.','verified',now())
   ON CONFLICT(sailor_id,regatta_id) DO UPDATE SET rank=excluded.rank,nett_score=excluded.nett_score,total_score=excluded.total_score,gender=excluded.gender,evidence_url=excluded.evidence_url,evidence_name=excluded.evidence_name,evidence_type=excluded.evidence_type,official_url=excluded.official_url,evidence_notes=excluded.evidence_notes,verification_status=excluded.verification_status,verified_at=excluded.verified_at,updated_at=now()
   RETURNING id INTO result_uuid;
   race_no := 0;
   FOR race IN SELECT value FROM jsonb_array_elements(item->'races') LOOP
    race_no := race_no+1;
    INSERT INTO public.regatta_race_results(regatta_result_id,race_number,score,scoring_code,discarded,raw_value)
    VALUES(result_uuid,race_no,(race->>'score')::real,race->>'code',(race->>'discarded')::boolean,race->>'raw')
    ON CONFLICT(regatta_result_id,race_number) DO UPDATE SET score=excluded.score,scoring_code=excluded.scoring_code,discarded=excluded.discarded,raw_value=excluded.raw_value,updated_at=now();
   END LOOP;
   DELETE FROM public.regatta_race_results WHERE regatta_result_id=result_uuid AND race_number>race_no;
   IF EXISTS(SELECT 1 FROM public.regatta_race_results WHERE regatta_result_id=result_uuid GROUP BY regatta_result_id HAVING count(*)<>race_no OR count(*) FILTER(WHERE discarded)<>1 OR sum(score)<>(item->>'total')::real OR sum(score) FILTER(WHERE NOT discarded)<>(item->>'nett')::real) THEN RAISE EXCEPTION 'Stored scores failed validation: %',item->>'name'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM public.regatta_results WHERE regatta_id=sheet_uuid)<>expected THEN RAISE EXCEPTION 'Unexpected roster size for %',fleet; END IF;
 END LOOP;
 UPDATE public.regatta_events SET classes='["Optimist Gold","Optimist Silver"]'::jsonb,nor_url='https://www.racingrulesofsailing.org/documents/8341/event',scoring_rules='Final results: Appendix A, one discard. Gold: 6 races, 5 counted. Silver: 5 races, 4 counted.',updated_at=now() WHERE id=event_uuid;
 INSERT INTO public.admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source)
 VALUES('regatta_results_import','regatta_event',event_uuid,'Raffles Marina Optimist Regatta 2024','Replaced Gold final scores (86 sailors, 6 races); added Silver final results (88 sailors, 5 races).',jsonb_build_object('source','https://www.racingrulesofsailing.org/documents/8341/event','gold_document',102965,'silver_document',102962,'entries',174,'race_scores',956,'visually_reviewed_pages',6),'official_results_import');
END
$import$;
